    )
    if heading is None:
        return None
    candidates = list(_ua068_re.finditer(
        r'<div\b(?=[^>]*\bclass=["\'][^"\']*\b(?:blok|krt)\b[^"\']*["\'])[^>]*>',
        source[:heading.start()],
        _ua068_re.I,
    ))
    for match in reversed(candidates):
        end = _ua068_balanced_div_end(source, match.start())
        if end >= heading.end():
