def sobrat_katalog(spisok, kadry_po_nomeru, legkie_po_nomeru=None):
    c = []
    c.append("<!doctype html><html lang='ru'><head><meta charset='utf-8'><!-- UA-ART-FAVICON-20260928 -->\n<link rel=\"icon\" href=\"/video/brand/ua-art/favicon.ico\" sizes=\"16x16 32x32 48x48\" type=\"image/x-icon\">\n<link rel=\"icon\" href=\"/video/brand/ua-art/favicon-96.png\" sizes=\"96x96\" type=\"image/png\">\n<link rel=\"apple-touch-icon\" href=\"/video/brand/ua-art/apple-touch-icon.png\" sizes=\"180x180\">\n<!-- /UA-ART-FAVICON-20260928 -->")
    c.append("<meta name='viewport' content='width=device-width,initial-scale=1'>")
    c.append("<script src='[URL]'></script>")
    c.append("<title>UA ART COMPANY — авто из Кореи</title><style>%s</style></head><body>" % STIL)
    c.append(shapka())
    c.append("<div class='zagolovok'>Авто в наличии и в пути</div>")
    c.append("<div class='schet'>%d в подборке · цены под ключ в Киеве</div>" % len(spisok))

    if not spisok:
        c.append("<div class='blok'>Сейчас витрина пуста — привезём под заказ из Кореи "
                 "за 45–60 дней с фиксированной ценой в договоре.</div>")

    for m in spisok:
        nom = nomer(m)
        kadry = kadry_po_nomeru.get(nom) or []
        sredn, mal = (legkie_po_nomeru or {}).get(nom) or (kadry, kadry)
        video_est = os.path.exists(os.path.join(PAPKA_VID, nom + ".mp4"))
        c.append("<a class='plitka' href='%s.html?v=%d'>" % (nom, int(time.time())))
        if kadry and sredn:
            c.append("<div class='ramka'><img src='%s' decoding='async' alt=''>" % sredn[0])
            if video_est:
                c.append("<div class='znak_video'><b>▶</b> видео</div>")
            c.append("</div>")
            if len(mal) > 1:
                c.append("<div class='mini_lenta'>")
                for k in mal[1:4]:
                    c.append("<img src='%s' loading='lazy' decoding='async' alt=''>" % k)
                if len(mal) > 4:
                    c.append("<div class='eshche'>+%d</div>" % (len(mal) - 4))
                c.append("</div>")
        c.append("<div class='telo'><div class='stroka'>")
        c.append("<div class='nazv'>%s</div>" % ekran(
            " ".join(str(x) for x in [m.get("brand"), m.get("model"), m.get("year")] if x)))
        c.append("<div class='cn'>%s</div></div>" % cena(m))
        c.append("<div class='niz'>%s · %s · %d фото%s</div></div></a>"
                 % (ekran(etap_korotko(m)), ekran(nom), len(kadry),
                    " · видео" if video_est else ""))

    c.append("<a class='vtoraya' href='podbor.html?v=%d'>Нужно другое — подберём под заказ</a>"
             % int(time.time()))
    c.append("<a class='vtoraya' href='index.html?v=%d'>← На главную</a>" % int(time.time()))
    c.append("<div class='blok'><div class='zag'>Как мы работаем</div>"
             "<div class='tihо' style='line-height:1.9'>"
             "1 · Подбираем варианты под бюджет<br>"
             "2 · Заключаем официальный договор. Предоплата — %d $, она входит "
             "в общую стоимость автомобиля. Цена фиксируется в договоре "
             "по курсу НБУ на дату его заключения.<br>"
             "3 · Проверяем историю и отчёт аукциона перед покупкой<br>"
             "4 · Стоянка в Корее, ждём погрузку<br>"
